#!/bin/sh
# Checks that Runtime/Core/Recorder/RecorderVersion.g.cs matches the version in package.json.
# The file is generated by the Unity editor (PLUME.Editor.RecorderVersionGenerator) and must be committed,
# since projects installing the package from git cannot regenerate it.
set -eu

root=$(cd "$(dirname "$0")/.." && pwd)
generated="$root/Runtime/Core/Recorder/RecorderVersion.g.cs"

pkg_version=$(tr -d '\r' < "$root/package.json" | sed -n 's/^[[:space:]]*"version"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)
if [ -z "$pkg_version" ]; then
  echo "check-version: could not read \"version\" from package.json" >&2
  exit 1
fi

if [ ! -f "$generated" ]; then
  echo "check-version: missing $generated" >&2
  exit 1
fi

field() {
  tr -d '\r' < "$generated" | sed -n "s/.*$1 = \"\([^\"]*\)\".*/\1/p" | head -n 1
}

gen_version=$(field PackageVersion)
core=${pkg_version%%+*}
core=${core%%-*}
expected_mmp=$core
actual_mmp="$(field Major).$(field Minor).$(field Patch)"

if [ "$gen_version" != "$pkg_version" ] || [ "$actual_mmp" != "$expected_mmp" ]; then
  echo "check-version: RecorderVersion.g.cs is out of date." >&2
  echo "  package.json:          $pkg_version" >&2
  echo "  RecorderVersion.g.cs:  $gen_version ($actual_mmp)" >&2
  echo "Open the project in Unity (or run 'PLUME/Regenerate Recorder Version') and commit the regenerated file." >&2
  exit 1
fi

echo "check-version: OK ($pkg_version)"
